showBarcode = true;

var rbValue;

/**
 * @param s - value from text field
 * @returns formatted string with fixed length
 */
function formatClearingNumber(s)
{
	s = s || "";
	switch(s.length){
		case 1: s = "000" + s; break;
		case 2: s = "00" + s; break;
		case 3: s = "0" + s; break;
	}
	return s;
}

/**
 * @param s - value from text field
 * @returns formatted string with fixed length
 */
function formatAccountNumber(s)
{
	s = s || "";
	switch(s.length){
		case 1: s = "00000" + s; break;
		case 2: s = "0000" + s; break;
		case 3: s = "000" + s; break;
		case 4: s = "00" + s; break;
		case 5: s = "0" + s; break;
	}
	return s;
}

/**
 * for standard pagination use:
 * soGlobal.getPagination(xfa.layout.page(this), xfa.layout.pageCount());
 *
 * if an attachement has its own pagination use:
 * soGlobal.getPagination(xfa.layout.page(this), xfa.layout.pageSpan(UBSForms.Page)); // for the regular form section
 * soGlobal.getPagination(this.resolveNode("MP_Attachment").index + 1, xfa.layout.pageSpan(UBSForms.Attachment)); // for the attachment
 *
 * different attachments need different pages!
 *
 * @param: {number} cp - current page
 * @param: {number} tp - total pages
 * @param: {string} page - hardcoded language string
 * @returns: formatted string
 */
function getPagination(cp, tp, page)
{
	tp = tp || xfa.layout.pageCount();
	if(!page){
		switch(Footer_Line_txtlanguage.value){
			case "DE":
				page = "Seite";
				break;
			case "EN":
			default:
				page = "Page";
		}
	}
	return page + " " + cp + "/" + tp;
}

/**
 * @param {string} p - pattern
 * @param {date} d - date object
 * @returns formatted date string using the provided pattern
 *
 * patterns are any combination of:
 * day: d (numeric, one digit), dd (numeric, two digits)
 * month: m (numeric, one digit), mm (numeric, two digits)
 * year: yyyy (numeric, four digits)
 * 
 * there is a special pattern: long (localized, long date) ex. June 2, 2000 or: 2 de junio de 2000
 */
function formatDate(p, d) 
{
	p = p && p.toLowerCase();
	d = d || new Date();

	var dd = d.getDate();
	var mm = d.getMonth()+1; 
	var yyyy = d.getFullYear();

	if(p)
	{
		if(p == "long") //Letter form date
		{
			switch(Footer_Line_txtlanguage.value)
			{
				case "DE":
					s = dd+". "+getMonth()+" "+yyyy;
					break;
				case "EN":
				default:
					s = getMonth()+" "+dd+", "+yyyy;
			}
			return s;
		}
		if(dd<10) 
		{
			dd='0'+dd;
		}
		if(mm<10) 
		{
			mm='0'+mm;
		}

		if(p == "dd.mm.yyyy") //Print current date
		{
			return dd + "." + mm + "." + yyyy;
		}

		if(p == "ddmmyyyy") //Barcode date
		{
			return "" + dd + mm + yyyy;
		}
	}
	return "00000000";
}
/**
 * returns combined first name and last name
 * 
 * @param {string} familyName
 * @param {string} firstName
 * @param {object} o - floating field/input field the full name should be pasted
 */
function setFullName(familyName, firstName, o)
{
	if(firstName && familyName){
		o.rawValue = firstName + " " + familyName;
	}	
}

/**
 * unselect radio button
 * on mouse down, use: soGlobal.rbValue = this.rawValue;
 * on mouse up use: this.rawValue = soGlobal.checkRadio(this.rawValue);
 *
 * @param: {string} value - radio button's raw value
 */
function checkRadioButton(value)
{
