function getMonth()
{
	var d = new Date();
	var en = ["January","February","March","April","Mai","June","July","August","September","October","November","December"];
	var it = ["Gennaio","Febbraio","Marzo","Aprile","Maggio","Giugno","Luglio","Agosto","Settembre","Ottobre","Novembre","Dicembre"];

	switch(Footer_Line_txtlanguage.value){
		case "DE": return it[d.getMonth()].toLowerCase();
		case "EN":
		default: return en[d.getMonth()];
	}
}       

