/**
* manually updates form configurator after coversheet is ready
*/
function _update()
{
       var o = Page.FormConfigurator_ClientType;
       var s = soFormset.clientType || soConfigClientType.getDefault();

       o.ClientType.CL_ClientType.rawValue = s;
       o.ClientType.CL_ClientType.access = "protected";
       soConfigClientType.selected = s;
       soLocalLabelDefinition.reset(false);

       if(soFormset.clients && soFormset.clients.length > 1){
           var node = Page.ClientDetails.DYN_FamilyName_FirstName;
           node.instanceManager.setInstances(soFormset.clients.length);
           Page.Signature.DYN_Signature.instanceManager.setInstances(soFormset.clients.length);
       }

       if(soFormset.entity && soFormset.entity.authReps.length > 1){
           Page.ClientDetails.DYN_FamilyName_FirstName.instanceManager.setInstances(soFormset.entity.authReps.length);
           Page.Signature.DYN_Signature.instanceManager.setInstances(soFormset.entity.authReps.length);
       }
}

function startPrefill()
{
	_prefillPage(Page);
	soSignatureLabel.onChange();
}

function _prefillPage(oPage)
{
	var o;
	var list;
	var value;

	_updateLayout(oPage);

	o = oPage.FormTitle.Subtitle_OneSignature;
	try{
		o.ffCreatedDate.rawValue = soFormset.creationDate;
	}catch(e){}

	o = oPage.ClientDetails.Company;
	try{
		value = soFormset.entity.name
		if(value){
			o.Company.rawValue = value;
			o.Company.access = "protected";
		}
	}catch(e){}

	list = oPage.ClientDetails.DYN_FamilyName_FirstName.all;
	for(var i=0,l=list.length,dyn,a; i<l; i++){
		dyn = list.item(i).FamilyName_FirstName;
		try{
			switch(soConfigClientType.selected){	
				case "Firma":
				case "GbR":
					value = soFormset.entity.authReps[i].familyName;
					if(value){
						dyn.TF_FamilyName.rawValue = value;
						dyn.TF_FamilyName.access = "protected";
					}
					value = soFormset.entity.authReps[i].firstName;
					if(value){
						dyn.TF_FirstName.rawValue = value;
						dyn.TF_FirstName.access = "protected";
					}
					break;
				default:
					value = soFormset.clients[i].familyName;
					if(value){
						dyn.TF_FamilyName.rawValue = value;
						dyn.TF_FamilyName.access = "protected";
					}
					value = soFormset.clients[i].firstName
					if(value){
						dyn.TF_FirstName.rawValue = value;
						dyn.TF_FirstName.access = "protected";
					}
			}
		}catch(e){}
	}

	o = oPage.Accountholder_securities.Asset_manager;
	try{
		value = soFormset.fim.name;
		if(value){
			o.NameOrCompanyname.NameCompanyname.rawValue = value;
			o.NameOrCompanyname.NameCompanyname.access = "protected";
		}
		value = soFormset.fim.postalCode;
		if(value){
			o.PostalCode_City_Country.TF_PostalCode.rawValue = value;	
			o.PostalCode_City_Country.TF_PostalCode.access = "protected";
		}
		value = soFormset.fim.city;
		if(value){
			o.PostalCode_City_Country.TF_City.rawValue = value;	
			o.PostalCode_City_Country.TF_City.access = "protected";			
		}
		value = soFormset.fim.country;
		if(value){
			o.PostalCode_City_Country.TF_Country.rawValue = value;
			o.PostalCode_City_Country.TF_Country.access = "protected";
		}
		value = soFormset.fim.street;
		if(value){
			o.Street_StreetNumber.TF_Street.rawValue = value;	
			o.Street_StreetNumber.TF_Street.access = "protected";	
		}
		value = soFormset.fim.streetNo
		if(value){
			o.Street_StreetNumber.TF_StreetNumber.rawValue = value;					
			o.Street_StreetNumber.TF_StreetNumber.access = "protected";
		}		
	}catch(e){}

	list = oPage.Signature.DYN_Signature.all;
	try{
		for(var i=0,l=list.length,oSign; i<l; i++){
			oSign = list.item(i).Signature;
			switch(soConfigClientType.selected){
				case "Firma":
				case "GbR":
					soGlobal.setFullName(soFormset.entity.authReps[i].familyName, soFormset.entity.authReps[i].firstName, oSign.FullName);
					break;
				case "Minderjährige":
					soGlobal.setFullName(soFormset.legalGuardians[i].familyName, soFormset.legalGuardians[i].firstName, oSign.FullName);
					break;
				default:
					soGlobal.setFullName(soFormset.clients[i].familyName, soFormset.clients[i].firstName, oSign.FullName);
					break;
			}
		}
	}catch(e){console.println(e)}

}

function _updateLayout(oPage)
{
	try{
		var n = soFormset.entity.authReps.length;
		oPage.ClientDetails.DYN_FamilyName_FirstName.instanceManager.setInstances(n);
		oPage.Signature.DYN_Signature.instanceManager.setInstances(n);
	}catch(e){}
}

event.script:
try{
	so61218.init();
}catch(e){}
try{
	if(soFormset){
		so61218._update();
	}
}catch(e){ console.println("** fail: 61218 _update"); }
try{
	if(soFormset){
		soPrefill.startPrefill();
	}
}catch(e){
	console.println("** fail: 61218 prefill");
	soSignatureLabel.onChange();
}
